import "server-only"
import createClient, { type Client } from "openapi-fetch"
import type { paths } from "./schema"

type ApiClient = Client<paths>
type Method = (...args: unknown[]) => Promise<unknown>

/**
 * The typed API client (spec 09). Server components and server actions only: the browser
 * never calls the API. Types come from `schema.d.ts`, generated by `npm run api:types`.
 *
 * `API_URL` is read on each request, not at import, because `next build` imports this
 * module without it. A client is built per request, so it also picks up Next's `fetch`.
 */
export const api = new Proxy({} as ApiClient, {
  get(_target, method) {
    return (...args: unknown[]) => {
      const baseUrl = process.env.API_URL
      if (!baseUrl) return Promise.reject(new Error("API_URL is not set"))
      const client = createClient<paths>({ baseUrl })
      return (Reflect.get(client, method) as Method)(...args)
    }
  },
})
